// @ts-nocheck
// #region 16. RENDER METRICS
import { THREE, RenderTarget } from "../core/deps.tsx"
import type { FramerRuntimeMode } from "../core/types.tsx"
import {
    _AUTO_FIT_MAX_ASPECT,
    _AUTO_FIT_MIN_VISIBLE,
} from "../core/constants.tsx"
import { _webglCoordinator } from "../bridge/coordinator.tsx"

let _mobileLikeCache = false
let _mobileLikeCacheAt = 0
let _mobileLikeCacheWidth = -1

/** Get visible width/height at a given distance from camera (works for both perspective & ortho). */
export function _getVisibleSize(camera: any, distance: number) {
    if (camera?.isOrthographicCamera) {
        return {
            width: (camera.right - camera.left) / Math.max(0.0001, camera.zoom),
            height:
                (camera.top - camera.bottom) / Math.max(0.0001, camera.zoom),
        }
    }
    const fov = ((camera?.fov ?? 35) * Math.PI) / 180
    const height = 2 * Math.tan(fov / 2) * Math.max(0.0001, distance)
    return {
        width: height * Math.max(0.0001, camera?.aspect || 1),
        height,
    }
}

/**
 * Auto-fit should be stable between Framer canvas and published desktop.
 * Published pages are often wider than the editor canvas; without this cap,
 * width-limited models grow larger after publish.
 */
export function _getAutoFitVisibleSize(camera: any, distance: number) {
    const visible = _getVisibleSize(camera, distance)
    const cappedWidth =
        visible.height *
        Math.min(camera.aspect || _AUTO_FIT_MAX_ASPECT, _AUTO_FIT_MAX_ASPECT)
    return {
        width: Math.min(visible.width, cappedWidth),
        height: visible.height,
    }
}

export function _getAutoFitRatio(camera: any, normSize: THREE.Vector3) {
    const distance = camera?.position?.length?.() || 1
    const visible = _getAutoFitVisibleSize(camera, distance)
    return (
        Math.min(
            visible.width / Math.max(_AUTO_FIT_MIN_VISIBLE, normSize.x),
            visible.height / Math.max(_AUTO_FIT_MIN_VISIBLE, normSize.y)
        ) * 0.85
    )
}

/** Cap render DPR to avoid expensive full-resolution rendering on high-DPI displays. */
export function _isMobileLike() {
    if (typeof window === "undefined") return false
    const now =
        typeof performance !== "undefined" ? performance.now() : Date.now()
    const width = window.innerWidth || 0
    if (
        _mobileLikeCacheAt &&
        now - _mobileLikeCacheAt < 1000 &&
        width === _mobileLikeCacheWidth
    ) {
        return _mobileLikeCache
    }

    _mobileLikeCacheAt = now
    _mobileLikeCacheWidth = width
    _mobileLikeCache =
        window.matchMedia?.("(pointer: coarse)")?.matches || width <= 768
    return _mobileLikeCache
}

export function _setStyleIfChanged(node: any, key: string, value: string) {
    if (!node?.style) return
    if (node.style[key] !== value) node.style[key] = value
}

export function _clearStyleIfChanged(node: any, key: string) {
    if (!node?.style) return
    if (node.style[key]) node.style[key] = ""
}

export function _getOptimizedDpr(cfg: any) {
    if (typeof window === "undefined") return 1
    const raw = window.devicePixelRatio || 1
    let cap = cfg.performanceMode
        ? (cfg.performanceDprCap ?? 1.5)
        : (cfg.performanceDprCap ?? 2)
    const mobile = _isMobileLike()
    if (mobile) {
        // Phones: fixed 1.5x (sharp, but bounded GPU memory on weak devices;
        // the multi-canvas multiplier still applies).
        cap = 1.5
    }
    // Multi-canvas: scale DPR cap down so total shaded pixels across the page
    // stay bounded as more canvases come alive.
    cap = cap * _webglCoordinator.getDprMultiplier()
    // Desktop: supersample up to 2x even on 1x monitors so thin CAD edges
    // don't crawl while the model moves.
    const target = mobile ? raw : Math.max(raw, 2)
    return Math.max(0.5, Math.min(target, cap))
}

export function _getOptimizedRenderMetrics(
    cssWidth: number,
    cssHeight: number,
    cfg: any
) {
    const safeWidth = Math.max(1, cssWidth || 1)
    const safeHeight = Math.max(1, cssHeight || 1)
    let dpr = _getOptimizedDpr(cfg)
    const maxPixelCount = cfg.performanceMaxPixelCount ?? 0
    if (maxPixelCount > 0) {
        const targetPixels = safeWidth * safeHeight * dpr * dpr
        if (targetPixels > maxPixelCount) {
            dpr = Math.max(
                0.1,
                Math.sqrt(maxPixelCount / (safeWidth * safeHeight))
            )
        }
    }
    return {
        dpr,
        renderWidth: Math.max(1, Math.round(safeWidth * dpr)),
        renderHeight: Math.max(1, Math.round(safeHeight * dpr)),
    }
}

export function _getOptimizedAnisotropy(renderer: any, cfg: any = null) {
    const maxAniso = renderer?.capabilities?.getMaxAnisotropy?.() ?? 1
    const cap = cfg?.performanceMode ? 4 : 4
    return Math.max(1, Math.min(maxAniso, cap))
}

export function _runtimeNeedsPostFx(cfg: any) {
    if (!cfg || cfg.cameraType === "stereo") return false
    // FXAA softens the model and colour grading alone forces a half-float
    // composer + extra full-screen passes every frame. Neither triggers the
    // composer any more: models render straight to the canvas (native MSAA,
    // renderer tone mapping) unless a real effect needs the pipeline.
    const structural = !!(
        cfg.bloomEnabled ||
        cfg.enableSSAO ||
        (cfg.enableDOF && cfg.cameraType !== "orthographic") ||
        cfg.enablePixelate
    )
    // Phones: only structural effects justify the composer.
    if (_isMobileLike()) return structural
    return !!(
        structural ||
        cfg.enableVignette ||
        cfg.enableChromaticAberration ||
        cfg.enableFilmGrain
    )
}

export function _postFxPipelineSignature(cfg: any) {
    if (!_runtimeNeedsPostFx(cfg)) return ""
    const needDof = !!(cfg.enableDOF && cfg.cameraType !== "orthographic")
    const needAlpha = !!(
        cfg.transparentBackground &&
        (cfg.bloomEnabled || needDof)
    )
    return [
        cfg.enableSSAO ? "ssao" : "",
        needAlpha ? "alpha" : "",
        needDof ? "dof" : "",
        cfg.bloomEnabled ? "bloom" : "",
        cfg.enableColorGrading ? "color" : "",
        cfg.enableVignette ? "vignette" : "",
        cfg.enableChromaticAberration ? "chromatic" : "",
        cfg.enableFilmGrain ? "grain" : "",
        cfg.enablePixelate ? "pixelate" : "",
        cfg.enableFXAA ? "fxaa" : "",
    ]
        .filter(Boolean)
        .join("|")
}

/**
 * Detect the current Framer runtime mode.
 * @param isOnFramerCanvas - result of useIsOnFramerCanvas() hook (optional,
 *   only available inside React render).  When omitted the function still
 *   detects canvas vs live via RenderTarget alone.
 */
export function getFramerRuntimeMode(
    isOnFramerCanvas?: boolean
): FramerRuntimeMode {
    const renderTarget = RenderTarget.current()
    if (renderTarget === RenderTarget.canvas || isOnFramerCanvas) {
        return "canvas"
    }
    if (
        renderTarget === (RenderTarget as any).preview &&
        typeof window !== "undefined" &&
        window.location.host.includes("framercanvas.com")
    ) {
        return "preview"
    }
    return "live"
}
// #endregion


/**
 * Keep the perspective depth range tight around the model. Depth precision is
 * set by near/far: a 0.01 near plane with the camera ~70 units away leaves
 * ~0.03-unit resolution, and CAD exports stack plates < 1 mm apart (HDD
 * cover, labels, PCB) -> z-fighting flicker, worst while the case opens.
 * Near/far hug the model's world bounding sphere (refreshed every 200 ms so
 * exploded / scroll-scaled parts stay inside), never looser than d/150..d*20.
 */
const _depthBox = new THREE.Box3()
const _depthSphere = new THREE.Sphere()
const _depthTmpBox = new THREE.Box3()
export function _fitCameraDepthRange(camera: any, target?: any) {
    if (!camera?.isPerspectiveCamera) return
    const d = camera.position?.length?.() || 10
    let near = Math.max(0.05, d / 150)
    let far = Math.max(100, d * 20)
    if (target) {
        const now =
            typeof performance !== "undefined" ? performance.now() : Date.now()
        const cache = target.userData || (target.userData = {})
        if (!cache._depthSphere || now - (cache._depthSphereAt || 0) > 200) {
            target.updateWorldMatrix?.(true, true)
            _depthBox.makeEmpty()
            target.traverse?.((o: any) => {
                if (!o.isMesh || !o.visible || !o.geometry) return
                if (!o.geometry.boundingBox) o.geometry.computeBoundingBox()
                const bb = o.geometry.boundingBox
                if (!bb || bb.isEmpty()) return
                _depthBox.union(_depthTmpBox.copy(bb).applyMatrix4(o.matrixWorld))
            })
            if (!_depthBox.isEmpty()) {
                _depthBox.getBoundingSphere(_depthSphere)
                cache._depthSphere = _depthSphere.clone()
            } else {
                cache._depthSphere = null
            }
            cache._depthSphereAt = now
        }
        const sphere = cache._depthSphere
        if (sphere && sphere.radius > 0) {
            const dist = camera.position.distanceTo(sphere.center)
            // 1.25x radius margin covers motion between refreshes.
            const r = sphere.radius * 1.25
            near = Math.max(near, dist - r)
            far = Math.min(far, Math.max(near * 2, dist + r))
        }
    }
    if (
        Math.abs(camera.near - near) > near * 0.01 ||
        Math.abs(camera.far - far) > far * 0.01
    ) {
        camera.near = near
        camera.far = far
        camera.updateProjectionMatrix()
    }
}


/**
 * Phones: cap model textures at 1024px (512 breaks the embossed logo). CAD exports ship 4096^2 atlases
 * (~90 MB of GPU memory each once decoded + mipmapped); three of them push weak
 * phones past the per-tab GPU limit, the browser kills the tab and the page
 * reloads (loader shows again). 1024 keeps weak phones well inside the GPU budget.
 * appears on a phone screen. Registered as a GLTFLoader plugin so every load
 * path (root, slot, preload) gets it before the textures reach the GPU.
 */
const _MOBILE_MAX_TEXTURE = 1024
const _TEXTURE_SLOTS = [
    "map",
    "normalMap",
    "roughnessMap",
    "metalnessMap",
    "aoMap",
    "emissiveMap",
    "alphaMap",
    "bumpMap",
    "clearcoatMap",
    "clearcoatNormalMap",
    "clearcoatRoughnessMap",
    "sheenColorMap",
    "sheenRoughnessMap",
    "specularColorMap",
    "specularIntensityMap",
    "transmissionMap",
    "thicknessMap",
    "iridescenceMap",
]
async function _downscaleTexture(tex: any, maxSize: number) {
    const img = tex?.image
    const w = img?.width || 0
    const h = img?.height || 0
    if (!w || !h || Math.max(w, h) <= maxSize) return
    const scale = maxSize / Math.max(w, h)
    const tw = Math.max(1, Math.round(w * scale))
    const th = Math.max(1, Math.round(h * scale))
    const canvas = document.createElement("canvas")
    canvas.width = tw
    canvas.height = th
    const ctx = canvas.getContext("2d")
    if (!ctx) return
    ctx.imageSmoothingEnabled = true
    ;(ctx as any).imageSmoothingQuality = "high"
    ctx.drawImage(img, 0, 0, tw, th)
    let next: any = canvas
    if (typeof createImageBitmap === "function") {
        try {
            next = await createImageBitmap(canvas, {
                imageOrientation: "none",
                premultiplyAlpha: "none",
            } as any)
            canvas.width = canvas.height = 0
        } catch {
            next = canvas
        }
    }
    img.close?.()
    tex.image = next
    tex.needsUpdate = true
}
export function _registerMobileTextureCap(loader: any) {
    if (!loader?.register || loader._mobileTextureCap) return loader
    loader._mobileTextureCap = true
    loader.register(() => ({
        name: "botanika_mobile_texture_cap",
        afterRoot: async (result: any) => {
            if (!_isMobileLike() || typeof document === "undefined") return
            const textures = new Set<any>()
            result?.scene?.traverse?.((o: any) => {
                if (!o.isMesh) return
                const mats = Array.isArray(o.material) ? o.material : [o.material]
                for (const m of mats) {
                    if (!m) continue
                    for (const k of _TEXTURE_SLOTS) if (m[k]) textures.add(m[k])
                }
            })
            await Promise.all(
                [...textures].map((t) =>
                    _downscaleTexture(t, _MOBILE_MAX_TEXTURE).catch(() => {})
                )
            )
        },
    }))
    return loader
}


/**
 * Phones render the 3D scene at most 60 fps. On 120 Hz screens we render every
 * other rAF tick (counter based, so frames stay evenly spaced); 60 Hz screens
 * render every tick. Time-based skipping caused uneven 1-2 frame gaps while
 * scrolling, which read as stutter.
 */
export const PHONE_TARGET_FPS = 60
export function _skipPhoneFrame(holder: any): boolean {
    if (!holder || !_isMobileLike()) return false
    const now =
        typeof performance !== "undefined" ? performance.now() : Date.now()
    const dt = holder._phoneTickAt ? now - holder._phoneTickAt : 16.7
    holder._phoneTickAt = now
    if (dt > 0 && dt < 100)
        holder._phoneTickEma = (holder._phoneTickEma ?? 16.7) * 0.9 + dt * 0.1
    const highRefresh = (holder._phoneTickEma ?? 16.7) < 11
    if (!highRefresh) return false
    holder._phoneTickN = ((holder._phoneTickN || 0) + 1) % 2
    return holder._phoneTickN === 1
}

/**
 * Frame-rate independent smoothing. The runtime eases scroll-driven motion
 * with "move X% of the remaining distance per frame", which speeds up/slows
 * down with the frame rate and stutters when frame times vary (phones while
 * scrolling). This converts a per-60fps-frame factor into the equivalent for
 * the real elapsed time; at a steady 60 fps it returns the factor unchanged.
 */
export function _timeLerp(holder: any, key: string, factor: number): number {
    if (!(factor < 1)) return 1
    const f = Math.max(0, factor)
    const now =
        typeof performance !== "undefined" ? performance.now() : Date.now()
    const last = holder?.[key]
    if (holder) holder[key] = now
    const dt = last ? Math.min(100, Math.max(0, now - last)) : 16.667
    const frames = dt / 16.667
    if (holder) holder[key + "_n"] = frames
    return 1 - Math.pow(1 - f, frames)
}


/**
 * Apply scene.environmentRotation (degrees). three.js copies the rotation into
 * a material's uniforms only when the material is (re)initialised, so a change
 * after the first render is ignored. When the value changes we flag the
 * scene's materials for update; the compiled programs are cached, so this is
 * a cheap refresh, and it only happens when the rotation actually changes.
 */
export function _applyEnvironmentRotation(scene: any, xDeg: number, yDeg: number) {
    if (!scene?.environmentRotation) return
    const key = `${xDeg || 0}|${yDeg || 0}`
    if (scene.userData?._envRotKey === key) return
    scene.environmentRotation.set(
        ((xDeg || 0) * Math.PI) / 180,
        ((yDeg || 0) * Math.PI) / 180,
        0
    )
    scene.userData = scene.userData || {}
    scene.userData._envRotKey = key
    scene.traverse((o: any) => {
        const mats = Array.isArray(o.material) ? o.material : o.material ? [o.material] : []
        for (const m of mats) m.needsUpdate = true
    })
}


/**
 * Upload everything the scene will need to the GPU while the loader is still
 * covering the page: textures (initTexture) and every mesh's vertex/index
 * buffers (one draw into a tiny offscreen target with frustum culling off, so
 * parts hidden inside the case are uploaded too). Without this the uploads
 * happen on the first visible frames -- exactly when the user starts scrolling.
 */
export function _warmGpuResources(renderer: any, scene: any, camera: any) {
    if (!renderer || !scene || !camera) return
    try {
        const textures = new Set<any>()
        const culled: any[] = []
        scene.traverse((o: any) => {
            if (o.isMesh || o.isPoints || o.isLine) {
                if (o.frustumCulled) {
                    culled.push(o)
                    o.frustumCulled = false
                }
                const mats = Array.isArray(o.material) ? o.material : o.material ? [o.material] : []
                for (const m of mats) {
                    for (const k of Object.keys(m)) {
                        const v = (m as any)[k]
                        if (v && v.isTexture) textures.add(v)
                    }
                }
            }
        })
        if (scene.environment?.isTexture) textures.add(scene.environment)
        for (const t of textures) {
            try {
                renderer.initTexture?.(t)
            } catch {}
        }
        const target = new THREE.WebGLRenderTarget(4, 4)
        const prevTarget = renderer.getRenderTarget()
        const prevScissor = renderer.getScissorTest?.()
        renderer.setScissorTest?.(false)
        renderer.setRenderTarget(target)
        renderer.render(scene, camera)
        renderer.setRenderTarget(prevTarget)
        if (prevScissor) renderer.setScissorTest?.(true)
        target.dispose()
        for (const o of culled) o.frustumCulled = true
    } catch {}
}
